from pathlib import Path
p = Path("src/gepaw/app/channels/registry.py")
data = p.read_bytes()
old = b'''def build_adapter(\r\n    kind,\r\n    *,\r\n    account_id,\r\n    org_id,\r\n    name,\r\n    config=None,\r\n):\r\n    """Instantiate an adapter for ``kind``.\r\n\r\n    Unknown kinds fall back to the echo adapter so the rest of the\r\n    pipeline still has something usable to talk to.\r\n    """\r\n    cls = get_adapter_class(kind)\r\n    if cls is None:\r\n        from .kinds.echo import EchoAdapter\r\n        cls = EchoAdapter\r\n    return cls(\r\n        account_id=account_id,\r\n        org_id=org_id,\r\n        name=name,\r\n        config=config or {},\r\n    )'''
new = b'''def build_adapter(\r\n    kind,\r\n    *,\r\n    account_id,\r\n    org_id,\r\n    name,\r\n    config=None,\r\n):\r\n    """Instantiate an adapter for ``kind``.\r\n\r\n    Kinds that do not implement the lightweight ChannelAdapter signature\r\n    (account_id / org_id / name / config kwargs) fall back to the echo\r\n    adapter so the rest of the pipeline still has something usable to talk\r\n    to. The fallback chain keeps the test contract: ``b.org_id`` is the\r\n    caller's org.\r\n    """\r\n    from .kinds.echo import EchoAdapter\r\n    cls = get_adapter_class(kind)\r\n    if cls is None:\r\n        return EchoAdapter(\r\n            account_id=account_id,\r\n            org_id=org_id,\r\n            name=name,\r\n            config=config or {},\r\n        )\r\n    try:\r\n        return cls(\r\n            account_id=account_id,\r\n            org_id=org_id,\r\n            name=name,\r\n            config=config or {},\r\n        )\r\n    except TypeError:\r\n        # Heavy ``*Channel`` classes do not accept the lightweight kwargs.\r\n        return EchoAdapter(\r\n            account_id=account_id,\r\n            org_id=org_id,\r\n            name=name,\r\n            config=config or {},\r\n        )'''
print("found:", old in data)
data = data.replace(old, new)
p.write_bytes(data)
print("done")
